refentry.refsect1:
&reftitle.description;
arrayintnullsscanf stringstring stringformat mixedvars
function sscanf, printf को input analog हो। sscanf ले string string from बाट पढ्छ र यसलाई निर्दिष्ट गरिएको format अनुसार interpret गर्छ। format string मा भएको कुनै पनि whitespace ले input string मा भएको कुनै पनि whitespace सँग match गर्छ। यसको अर्थ format string मा भएको एउटा tab (\t) ले समेत input string मा भएको एउटा single space character सँग match गर्न सक्छ।

&reftitle.parameters;


  string

   Parse गरिने input string।


 &strings.scanf.parameter.format;

  vars

   वैकल्पिक रूपमा variable हरूलाई reference मार्फत pass गर्नुहोस्, जसमा parse गरिएका values समावेश हुनेछन्।

  &reftitle.examples;

   sscanf को उदाहरण


<?php
// getting the serial number
list($serial) = sscanf("SN/2350001", "SN/%d");
// and the date of manufacturing
$mandate = "January 01 2000";
list($month, $day, $year) = sscanf($mandate, "%s %d %d");
echo "Item $serial was manufactured on: $year-" . substr($month, 0, 3) . "-$day\n";
?>



  यदि optional parameters pass गरियो भने, function ले assign गरिएका values को संख्या return गर्नेछ।

   sscanf - ऐच्छिक parameters प्रयोग गरेर


<?php
// get author info and generate DocBook entry
$auth = "24\tLewis Carroll";
$n = sscanf($auth, "%d\t%s %s", $id, $first, $last);
echo "<author id='$id'>
    <firstname>$first</firstname>
    <surname>$last</surname>
</author>\n";
?>
